"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";

export interface StatProps extends React.HTMLAttributes<HTMLDivElement> {
  label: React.ReactNode;
  value: React.ReactNode;
  icon?: React.ReactNode;
  /** Kleur van het icoonvlak. */
  tone?: "accent" | "green" | "amber" | "red" | "blue" | "violet";
  /** Verandering t.o.v. vorige periode, bv. +12.4. */
  delta?: number;
  /** Tekst achter de delta, bv. "vs. vorige maand". */
  deltaLabel?: React.ReactNode;
  /** Kleine grafiek onderaan (bv. <Sparkline/>). */
  chart?: React.ReactNode;
}

/** Stat — KPI-tegel met waarde, icoon en trend. */
export const Stat = React.forwardRef<HTMLDivElement, StatProps>(function Stat(
  { label, value, icon, tone = "accent", delta, deltaLabel, chart, className, ...rest },
  ref
) {
  const direction = delta === undefined ? null : delta >= 0 ? "up" : "down";

  return (
    <div ref={ref} className={cn("pxui-stat", className)} {...rest}>
      <div className="pxui-stat-top">
        <span className="pxui-stat-label">{label}</span>
        {icon && <span className={cn("pxui-stat-icon", `pxui-stat-icon-${tone}`)}>{icon}</span>}
      </div>
      <div className="pxui-stat-value">{value}</div>
      {direction && (
        <div className={cn("pxui-stat-delta", `pxui-stat-delta-${direction}`)}>
          <Icon name={direction === "up" ? "arrowUp" : "arrowDown"} size={13} />
          {Math.abs(delta as number)}%
          {deltaLabel && <span className="pxui-stat-delta-label">{deltaLabel}</span>}
        </div>
      )}
      {chart && <div className="pxui-stat-chart">{chart}</div>}
    </div>
  );
});

/** Raster dat KPI-tegels netjes uitlijnt. */
export const StatGrid = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & { min?: number }
>(function StatGrid({ min = 200, className, style, ...rest }, ref) {
  return (
    <div
      ref={ref}
      className={cn("pxui-stat-grid", className)}
      style={{ gridTemplateColumns: `repeat(auto-fit, minmax(${min}px, 1fr))`, ...style }}
      {...rest}
    />
  );
});

/* ============================ Stat (KPI) ============================ */
.pxui-stat-grid { display: grid; gap: 16px; }

.pxui-stat {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-lg); box-shadow: var(--sh-sm);
  padding: 18px 20px; display: flex; flex-direction: column; min-width: 0;
}
.pxui-stat-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.pxui-stat-label { font-size: 13px; color: var(--text-3); font-weight: 550; }
.pxui-stat-icon {
  display: grid; place-items: center; width: 34px; height: 34px;
  border-radius: 9px; flex: none;
}
.pxui-stat-icon svg { width: 17px; height: 17px; }
.pxui-stat-icon-accent { background: var(--accent-tint); color: var(--accent); }
.pxui-stat-icon-green { background: var(--green-tint); color: var(--green); }
.pxui-stat-icon-amber { background: var(--amber-tint); color: var(--amber); }
.pxui-stat-icon-red { background: var(--red-tint); color: var(--red); }
.pxui-stat-icon-blue { background: var(--blue-tint); color: var(--blue); }
.pxui-stat-icon-violet { background: var(--violet-tint); color: var(--violet); }

.pxui-stat-value {
  font-size: 30px; font-weight: 700; letter-spacing: -0.03em;
  margin-top: 10px; line-height: 1; color: var(--text);
}
.pxui-stat-delta {
  font-size: var(--fs-sm); font-weight: 600; margin-top: 7px;
  display: inline-flex; align-items: center; gap: 4px;
}
.pxui-stat-delta-up { color: var(--green); }
.pxui-stat-delta-down { color: var(--red); }
.pxui-stat-delta-label { color: var(--text-3); font-weight: 500; margin-left: 3px; }
.pxui-stat-chart { margin-top: 14px; }
